"""Independent check of fvec: enumerate W_J as signed permutations generated by simple reflections,
classify each element directly (signed cycle type + split sign via conjugating diagonal parity)."""
from dchar import *
from fractions import Fraction
import random, sys
from itertools import combinations

def gens(n):
    G = []
    for i in range(1, n):  # s_i swaps i,i+1 (0-based i-1,i)
        G.append((i, tuple((j, 1) for j in range(n)), i - 1, i, 1))
    out = {}
    for i in range(1, n):
        p = list(range(n)); s = [1]*n; p[i-1], p[i] = p[i], p[i-1]; out[i] = (tuple(p), tuple(s))
    p = list(range(n)); s = [1]*n; p[n-2], p[n-1] = p[n-1], p[n-2]; s[n-2] = s[n-1] = -1
    out[n] = (tuple(p), tuple(s))
    return out
# element: w(e_j) = sg[j] e_{p[j]}
def mul(a, b):  # a*b: apply b then a
    pa, sa = a; pb, sb = b
    return (tuple(pa[pb[j]] for j in range(len(pa))), tuple(sb[j]*sa[pb[j]] for j in range(len(pa))))

def classify(w):
    p, s = w; n = len(p); seen = [0]*n; lam, mu = [], []; cyc = []
    for j in range(n):
        if seen[j]: continue
        c = []; k = j; sign = 1
        while not seen[k]: seen[k] = 1; c.append(k); sign *= s[k]; k = p[k]
        (lam if sign > 0 else mu).append(len(c)); cyc.append(c)
    lam = tuple(sorted(lam, reverse=True)); mu = tuple(sorted(mu, reverse=True))
    sg = 0
    if not mu and all(x % 2 == 0 for x in lam):
        # find diagonal eps with eps w eps = unsigned: along each cycle propagate eps[p[k]] = s[k]*eps[k]
        eps = [0]*n
        for c in cyc:
            eps[c[0]] = 1
            for k in c[:-1]: eps[p[k]] = s[k]*eps[k]
        neg = sum(1 for e in eps if e < 0)
        sg = 1 if neg % 2 == 0 else -1
    return (lam, mu, sg)

def fbrute(n, J):
    g = gens(n); idn = (tuple(range(n)), (1,)*n)
    S = {idn}; fr = [idn]
    while fr:
        nf = []
        for w in fr:
            for j in J:
                x = mul(g[j], w)
                if x not in S: S.add(x); nf.append(x)
        fr = nf
    G = D(n); cnt = {}
    for w in S:
        c = G.cidx[classify(w)]; cnt[c] = cnt.get(c, 0) + 1
    sg = G.sgn()
    return tuple(int(Fraction(sum(k*sg[c]*row[c] for c, k in cnt.items()), len(S))) for row in G.table), len(S)

n = int(sys.argv[1]); maxord = int(sys.argv[2])
random.seed(1); bad = tested = 0
Js = [frozenset(J) for k in range(n+1) for J in combinations(range(1, n+1), k)]
for J in Js:
    ks, m = J_blocks(n, frozenset(n-1 if j == n else j for j in J)) if (n in J and n-1 not in J) else J_blocks(n, J)
    from math import factorial
    o = D(m).order
    for x in ks: o *= factorial(x)
    if o > maxord: continue
    fb, sz = fbrute(n, J); tested += 1
    assert sz == o
    if fb != fvec(n, J): bad += 1; print('MISMATCH', sorted(J))
print(f'D{n}: tested {tested} J, mismatches {bad}')
